INSERT INTO public.quan_he_hieu_luc (so_hieu_nguon, so_hieu_dich, loai, hieu_luc_tu, do_tin_cay, co_ngoai_le, ma_cong_bao_nguon, trich) VALUES
('83/2015/QH13', '01/2002/QH11', 'bai_bo', '2017-01-01', 'chac_chan', false, '15368', '2. Luật ngân sách nhà nước số 01/2002/QH11 hết hiệu lực kể từ ngày Luật này có hiệu lực thi hành.'),
('03/2012/NQ-HĐTP', '01/2005/NQ-HĐTP', 'bai_bo', '2013-07-01', 'chac_chan', false, '5730', '1. Nghị quyết này đã được Hội đồng Thẩm phán Tòa án nhân dân tối cao thông qua ngày 03-12-2012 và có hiệu lực thi hành kể từ ngày 01-7-2013. Nghị quyết số 01/2005/NQ-HĐTP ngày 31-3-2005 của Hội đồng Thẩm phán Tòa án nhân dân tối cao hướng dẫn thi hành một số quy định trong Phần thứ nhất “Những quy định chung” của Bộ luật Tố tụng dân sự và hướng dẫn về các vấn đề đã được hướng dẫn tại Nghị quyết này của Tòa án nhân dân tối cao ban hành trước ngày Nghị quyết này có hiệu lực thi hành hết hiệu lực thi hành kể từ ngày 01-7-2013.'),
('17/2015/TT-BLĐTBXH', '01/2005/TT-BLĐTBXH', 'bai_bo', '2015-06-10', 'chac_chan', false, '11847', '…2. Các Thông tư do Bộ Lao động - Thương binh và Xã hội ban hành sau đây hết hiệu lực thi hành kể từ ngày Thông tư này có hiệu lực thi hành, bao gồm: a) Thông tư số 01/2005/TT-BLĐTBXH ngày 05 tháng 01 năm 2005 hướng dẫn chuyển xếp lương cũ sang lương mới đối với Tổng giám đốc, Giám đốc, Phó tổng giám đốc, Phó giám đốc, Kế toán trưởng và công nhân, viên chức, nhân viên trong các công ty nhà nước theo Nghị định số 205/2004/NĐ-CP ngày 14 tháng 12 năm 2005 của Chính phủ; b) Thông tư số 04/1998/TT-BLĐTBXH ngày 04 tháng 4 năm 1998 hướng dẫn xây dựng tiêu chuẩn và thi nâng ngạch viên chức chuyên môn, nghiệp vụ trong doanh nghiệp nhà nước; c) Thông tư số 12/2003/TT-BLĐTBXH ngày 30 tháng 5 năm 2003 hướng dẫn thực hiện một số điều của Nghị định số 114/2002/NĐ-CP ngày 31 tháng 12 năm 2002 của Chính phủ về tiền lương đối với người lao động làm việc trong doanh nghiệp nhà nước; d) Thông tư số 18/2008/TT-BLĐTBXH ngày 16 tháng 9 năm 2008 sửa đổi, bổ sung Thông tư số 12/2003/TT-BLĐTBXH ngày 30 tháng 5 năm 2003 hướng dẫn thực hiện một số điều của Nghị định số 114/2002/NĐ-CP ngày 31 tháng 12 năm 2002 của Chính phủ về tiền lương; đ) Thông tư số 03/2005/TT-BLĐTBXH ngày 05 tháng 01 năm 2005 hướng dẫn th…'),
('137/2017/TT-BTC', '01/2007/TT-BTC', 'bai_bo', '2018-02-10', 'chac_chan', false, '26045', '2. Thông tư số 01/2007/TT-BTC ngày 02 tháng 01 năm 2007 của Bộ Tài chính hướng dẫn xét duyệt, thẩm định và thông báo quyết toán năm đối với cơ quan hành chính, đơn vị sự nghiệp, tổ chức được ngân sách nhà nước hỗ trợ và ngân sách các cấp hết hiệu lực thi hành kể từ ngày Thông tư này có hiệu lực thi hành.'),
('39/2013/TT-BYT', '01/2007/TT-BYT', 'bai_bo', '2014-01-01', 'chac_chan', false, '6312', '…2. Thông tư số 01/2007/TT-BYT ngày 17 tháng 01 năm 2007 của Bộ trưởng Bộ Y tế hướng dẫn quản lý thuốc chữa bệnh cho người theo đường xuất khẩu, nhập khẩu phi mậu dịch hết hiệu lực kể từ ngày Thông tư này có hiệu lực. Trong quá trình thực hiện, nếu có khó khăn, vướng mắc, đề nghị cơ quan, tổ chức, cá nhân phản ánh kịp thời về Bộ Y tế (Cục Quản lý Dược) để được hướng dẫn hoặc sửa đổi, bổ sung cho phù hợp./. KT. BỘ TRƯỞNG THỨ TRƯỞNG Phạm Lê Tuấn Mẫu số 1a/PMD (Ban hành kèm theo Thông tư số 39/2013/TT-BYT ngày 15 tháng 11 năm 2013 của Bộ trưởng Bộ Y tế) CỘNG HÒA XÃ HỘI CHỦ NGHĨA VIỆT NAM Độc lập - Tự do - Hạnh phúc ĐƠN ĐỀ NGHỊ XUẤT/NHẬP KHẨU THUỐC THEO ĐƯỜNG PHI MẬU DỊCH (Thuốc gây nghiện) Kính gửi: Cục Quản lý Dược Tôi là............................................................................................ năm sinh.......... Nơi đăng ký hộ khẩu thường trú (đối với người Việt Nam)................................. Chỗ ở hiện tại (chỗ ở tại Việt Nam):..................................................................... Điện thoại.............................................................................................................. Số chứng minh thư (Hộ chiếu)................…'),
('20/2011/TT-BYT', '01/2008/TT-BYT', 'bai_bo', '2011-08-15', 'chac_chan', false, '11698', '2. Thông tư số 01/2008/TT-BYT ngày 22/01/2008 của Bộ trưởng Bộ Y tế hướng dẫn công tác thi đua, khen thưởng trong ngành Y tế hết hiệu lực kể từ ngày Thông tư này có hiệu lực.'),
('37/2020/QĐ-TTg', '01/2009/QĐ-TTg', 'bai_bo', '2021-02-20', 'chac_chan', false, '32848', '2. Các Quyết định số 01/2009/QĐ-TTg ngày 02 tháng 01 năm 2009 của Thủ tướng Chính phủ về việc thành lập Sở giao dịch Chứng khoán Hà Nội, Quyết định số 599/2007/QĐ-TTg ngày 11 tháng 5 năm 2007 của Thủ tướng Chính phủ về chuyển Trung tâm Giao dịch chứng khoán thành phố Hồ Chí Minh thành Sở giao dịch Chứng khoán thành phố Hồ Chí Minh, Quyết định số 21/2015/QĐ-TTg ngày 18 tháng 6 năm 2015 sửa đổi một số điều của Quyết định số 599/2007/QĐ-TTg của Thủ tướng Chính phủ hết hiệu lực kể từ ngày Sở giao dịch Chứng khoán Việt Nam bắt đầu hoạt động theo quy định tại khoản 1 Điều 8 Quyết định này.'),
('11/2016/TT-BYT', '01/2012/TTLT-BYT-BTC', 'bai_bo', '2016-07-01', 'chac_chan', false, '19800', '2. Các văn bản sau đây hết hiệu lực thi hành kể từ ngày Thông tư này có hiệu lực: a) Thông tư liên tịch số 01/2012/TTLT-BYT-BTC ngày 19 tháng 01 năm 2012 của liên Bộ Y tế - Bộ Tài chính hướng đấu thầu mua thuốc trong các cơ sở y tế; b) Thông tư liên tịch số 36/2013/TTLT-BYT-BTC ngày 11 tháng 11 năm 2013 của liên Bộ Y tế - Bộ Tài chính sửa đổi, bổ sung một số điều của Thông tư liên tịch số 01/2012/TTLT-BYT-BTC ngày 19 tháng 01 năm 2012 của liên Bộ Y tế - Bộ Tài chính hướng đấu thầu mua thuốc trong các cơ sở y tế; c) Thông tư số 37/2013/TT-BYT ngày 11 tháng 11 năm 2013 của Bộ trưởng Bộ Y tế hướng dẫn lập hồ sơ mời thầu mua thuốc trong các cơ sở y tế; d) Thông tư số 31/2014/TT-BYT ngày 26 tháng 9 năm 2014 của Bộ trưởng Bộ Y tế quy định Bảng tiêu chuẩn đánh giá về mặt kỹ thuật tại hồ sơ mời thầu mua thuốc.'),
('85/2025/TT-BTC', '01/2014/QĐ-TTg', 'bai_bo', '2025-10-10', 'can_xem_lai', false, '46293', '2. Thông tư số 137/2014/TT-BTC ngày 18 tháng 9 năm 2014 của Bộ Tài chính hướng dẫn về lập dự toán, chấp hành và quyết toán kinh phí chi trả tiền bồi dưỡng giám định tư pháp của các cơ quan tiến hành tố tụng theo quy định tại Quyết định số 01/2014/QĐ-TTg hết hiệu lực kể từ ngày Thông tư này có hiệu lực thi hành.'),
('09/2015/TT-BXD', '01/2014/TT-BXD', 'bai_bo', '2016-02-16', 'chac_chan', false, '18943', '2. Thông tư số 01/2014/TT-BXD ngày 16 tháng 01 năm 2014 của Bộ trưởng Bộ Xây dựng hướng dẫn việc quản lý sử dụng nhà ở công vụ và Thông tư liên tịch số 04/2013/TTLT-BXD-BTC ngày 22 tháng 4 năm 2013 của Bộ trưởng Bộ Xây dựng và Bộ trưởng Bộ Tài chính quy định tiêu chuẩn, định mức trang bị nội thất cơ bản nhà ở công vụ của Chính phủ hết hiệu lực thi hành kể từ ngày Thông tư này có hiệu lực thi hành.'),
('31/2019/TT-BTC', '01/2015/TTLT-BNV-BTC', 'bai_bo_mot_phan', '2019-07-25', 'chac_chan', false, '29174', '2. Chương III Thông tư liên tịch số 01/2015/TTLT-BNV-BTC ngày 14 tháng 4 năm 2015 của Bộ Nội vụ, Bộ Tài chính hướng dẫn một số điều của Nghị định số 108/2014/NĐ-CP ngày 20 tháng 11 năm 2014 của Chính phủ về chính sách tinh giản biên chế hết hiệu lực kể từ ngày Thông tư này có hiệu lực thi hành.'),
('01/2026/TT-BTC', '01/2018/TT-BTC', 'bai_bo', '2026-02-20', 'chac_chan', false, '468744', '2. Các Thông tư sau hết hiệu lực thi hành kể từ ngày Thông tư này có hiệu lực thi hành: a) Thông tư số 01/2018/TT-BTC ngày 02 tháng 01 năm 2018 của Bộ trưởng Bộ Tài chính quy định việc quản lý và sử dụng kinh phí bảo đảm trật tự an toàn giao thông; b) Thông tư số 28/2019/TT-BTC ngày 21 tháng 5 năm 2019 của Bộ trưởng Bộ Tài chính sửa đổi, bổ sung một số điều của Thông tư số 01/2018/TT-BTC ngày 02 tháng 01 năm 2018 của Bộ trưởng Bộ Tài chính quy định việc quản lý và sử dụng kinh phí bảo đảm trật tự an toàn giao thông.'),
('68/2025/TT-BTC', '01/2021/TT-BKHĐT', 'bai_bo', '2025-07-01', 'chac_chan', false, '45617', '3. Các thông tư sau hết hiệu lực kể từ ngày Thông tư này có hiệu lực thi hành: a) Thông tư số 01/2021/TT-BKHĐT ngày 16 tháng 3 năm 2021 của Bộ trưởng Bộ Kế hoạch và Đầu tư hướng dẫn về đăng ký doanh nghiệp; b) Thông tư số 02/2023/TT-BKHĐT ngày 18 tháng 4 năm 2023 của Bộ trưởng Bộ Kế hoạch và Đầu tư sửa đổi, bổ sung một số điều của Thông tư số 01/2021/TT-BKHĐT ngày 16 tháng 3 năm 2021 hướng dẫn về đăng ký doanh nghiệp.'),
('74/2025/TT-BTC', '01/2024/TT-BTC', 'bai_bo', '2025-08-18', 'chac_chan', false, '45470', '2. Thông tư số 01/2024/TT-BTC ngày 08 tháng 01 năm 2024 của Bộ trưởng Bộ Tài chính quy định thời hạn bảo quản hồ sơ, tài liệu chuyên môn, nghiệp vụ ngành Tài chính hết hiệu lực kể từ ngày Thông tư này có hiệu lực.'),
('47/2010/QH12', '02/1997/QH10', 'bai_bo', '2011-01-01', 'chac_chan', false, '3099', '2. Luật Các tổ chức tín dụng số 02/1997/QH10 và Luật Sửa đổi, bổ sung một số điều của Luật Các tổ chức tín dụng số 20/2004/QH11 hết hiệu lực kể từ ngày Luật này có hiệu lực.'),
('62/2014/QH13', '02/2002/PL-UBTVQH11', 'bai_bo', '2015-06-01', 'can_xem_lai', true, '12678', '2. Luật này thay thế Luật tổ chức Tòa án nhân dân số 33/2002/QH10. Pháp lệnh Thẩm phán và Hội thẩm Tòa án nhân dân số 02/2002/PL-UBTVQH11, Pháp lệnh sửa đổi, bổ sung một số điều của Pháp lệnh Thẩm phán và Hội thẩm Tòa án nhân dân số 14/2011/PL-UBTVQH12 hết hiệu lực kể từ ngày Luật này có hiệu lực thi hành. Pháp lệnh tổ chức Tòa án quân sự số 04/2002/PL-UBTVQH11 hết hiệu lực kể từ ngày Luật này có hiệu lực thi hành, trừ các quy định tại các Điều 3, 4, 5, khoản 1 Điều 26, khoản 2 Điều 29 tiếp tục có hiệu lực thi hành cho đến khi bị hủy bỏ. Luật này đã được Quốc hội nước Cộng hòa xã hội chủ nghĩa Việt Nam khóa XIII, kỳ họp thứ 8 thông qua ngày 24 tháng 11 năm 2014./. CHỦ TỊCH QUỐC HỘI Nguyễn Sinh Hùng'),
('35/2011/TT-BYT', '02/2004/TT-BYT', 'bai_bo', '2011-12-01', 'chac_chan', false, '13241', '2. Thông tư số 02/2004/TT-BYT của Bộ Y tế ngày 20 tháng 01 năm 2004 hướng dẫn thực hiện công tác chăm sóc sức khỏe người cao tuổi hết hiệu lực thi hành kể từ ngày Thông tư này có hiệu lực thi hành. Trong quá trình thực hiện, nếu có vướng mắc, các đơn vị, các địa phương phản ánh về Bộ Y tế (Cục Quản lý Khám, chữa bệnh) để được hướng dẫn, xem xét, giải quyết hoặc bổ sung, sửa đổi cho phù hợp./. KT. BỘ TRƯỞNG THỨ TRƯỞNG Nguyễn Thị Xuyên'),
('10/2014/TT-NHNN', '02/2008/QĐ-NHNN', 'bai_bo', '2014-06-01', 'chac_chan', false, '5157', '2. Các quyết định sau của Thống đốc Ngân hàng Nhà nước hết hiệu lực kể từ ngày Thông tư này có hiệu lực thi hành: a) Quyết định số 807/2005/QĐ-NHNN ngày 01/6/2005 về việc sửa đổi, bổ sung một số tài khoản trong Hệ thống tài khoản kế toán các tổ chức tín dụng ban hành kèm theo Quyết định số 479/2004/QĐ-NHNN ngày 29/4/2004 của Thống đốc Ngân hàng Nhà nước; b) Quyết định số 29/2006/QĐ-NHNN ngày 10/7/2006 về việc sửa đổi, bổ sung, hủy bỏ một số tài khoản trong Hệ thống tài khoản kế toán các tổ chức tín dụng ban hành theo Quyết định số 479/2004/QĐ-NHNN ngày 29/4/2004 và Quyết định số 807/2005/QĐ-NHNN ngày 01/6/2005 của Thống đốc Ngân hàng Nhà nước; c) Quyết định số 02/2008/QĐ-NHNN ngày 15/01/2008 về việc sửa đổi, bổ sung một số tài khoản trong Hệ thống tài khoản kế toán các Tổ chức tín dụng ban hành theo Quyết định số 479/2004/QĐ-NHNN ngày 29/4/2004, Quyết định số 807/2005/QĐ-NHNN ngày 01/6/2005 và Quyết định số 29/2006/QĐ-NHNN ngày 10/7/2006 của Thống đốc Ngân hàng Nhà nước.'),
('03/2018/TT-NHNN', '02/2008/TT-NHNN', 'bai_bo', '2018-02-23', 'chac_chan', false, '25988', '2. Kể từ ngày Thông tư này có hiệu lực thi hành, các quy định về cấp Giấy phép, tổ chức và hoạt động tại Thông tư số 02/2008/TT-NHNN ngày 02/4/2008 của Thống đốc Ngân hàng Nhà nước hướng dẫn thực hiện Nghị định số 28/2005/NĐ-CP ngày 09/3/2005 của Chính phủ về tổ chức và hoạt động của tổ chức tài chính quy mô nhỏ tại Việt Nam và Nghị định số 165/2007/NĐ-CP ngày 15/11/2007 của Chính phủ sửa đổi, bổ sung, bãi bỏ một số điều của Nghị định số 28/2005/NĐ-CP ngày 09/3/2005 của Chính phủ về tổ chức và hoạt động của tổ chức tài chính quy mô nhỏ tại Việt Nam hết hiệu lực thi hành.'),
('91/2024/TT-BTC', '02/2019/TT-BTC', 'bai_bo', '2025-03-01', 'chac_chan', false, '43997', '3. Thông tư số 02/2019/TT-BTC ngày 14 tháng 01 năm 2019 của Bộ Tài chính Quy định Chế độ báo cáo thống kê ngành Tài chính hết hiệu lực kể từ ngày Thông tư này có hiệu lực thi hành trừ quy định tại khoản 2 Điều này.'),
('68/2025/TT-BTC', '02/2023/TT-BKHĐT', 'bai_bo', '2025-07-01', 'chac_chan', false, '45617', '3. Các thông tư sau hết hiệu lực kể từ ngày Thông tư này có hiệu lực thi hành: a) Thông tư số 01/2021/TT-BKHĐT ngày 16 tháng 3 năm 2021 của Bộ trưởng Bộ Kế hoạch và Đầu tư hướng dẫn về đăng ký doanh nghiệp; b) Thông tư số 02/2023/TT-BKHĐT ngày 18 tháng 4 năm 2023 của Bộ trưởng Bộ Kế hoạch và Đầu tư sửa đổi, bổ sung một số điều của Thông tư số 01/2021/TT-BKHĐT ngày 16 tháng 3 năm 2021 hướng dẫn về đăng ký doanh nghiệp.'),
('63/2014/QH13', '03/2002/PL-UBTVQH11', 'bai_bo', '2015-06-01', 'can_xem_lai', false, '12676', '3. Luật tổ chức Viện kiểm sát nhân dân số 34/2002/QH10, Pháp lệnh Kiểm sát viên Viện kiểm sát nhân dân số 03/2002/PL-UBTVQH11 đã được sửa đổi, bổ sung một số điều theo Pháp lệnh số 15/2011/PL-UBTVQH12, Pháp lệnh tổ chức Viện kiểm sát quân sự số 05/2002/PL-UBTVQH11 hết hiệu lực kể từ ngày Luật này có hiệu lực.'),
('88/2015/QH13', '03/2003/QH11', 'bai_bo', '2017-01-01', 'chac_chan', false, '18393', '2. Luật kế toán số 03/2003/QH11 hết hiệu lực kể từ ngày Luật này có hiệu lực thi hành.'),
('214/2012/TT-BTC', '03/2005/QĐ-BTC', 'bai_bo', '2014-01-01', 'can_xem_lai', false, '2556', '3. Hệ thống chuẩn mực kiểm toán Việt Nam ban hành theo các Quyết định số 120/1999/QĐ-BTC ngày 27/9/1999, Quyết định số 219/2000/QĐ-BTC ngày 29/12/2000, Quyết định số 143/2001/QĐ-BTC ngày 21/12/2001, Quyết định số 28/2003/QĐ-BTC ngày 14/3/2003, Quyết định số 195/2003/QĐ-BTC ngày 28/11/2003, Quyết định số 03/2005/QĐ-BTC ngày 18/01/2005, Quyết định số 101/2005/QĐ-BTC ngày 29/12/2005 của Bộ trưởng Bộ Tài chính hết hiệu lực kể từ ngày 01/01/2014, trừ các chuẩn mực quy định tại khoản 4 Điều này.'),
('67/2015/TT-BTC', '03/2005/QĐ-BTC', 'bai_bo', '2015-07-01', 'chac_chan', false, '15528', '3. Thông tư này có hiệu lực thi hành kể từ ngày 01/7/2015. Đối với các hợp đồng kiểm toán báo cáo quyết toán dự án hoàn thành được thực hiện trước ngày 01/7/2015 mà đến ngày 01/7/2015 trở đi mới phát hành báo cáo kiểm toán thì phải áp dụng Chuẩn mực kiểm toán Việt Nam về kiểm toán báo cáo quyết toán dự án hoàn thành ban hành theo Thông tư này. Chuẩn mực kiểm toán số 1000 “Kiểm toán báo cáo quyết toán vốn đầu tư hoàn thành” ban hành theo Quyết định số 03/2005/QĐ-BTC ngày 18/01/2005 của Bộ trưởng Bộ Tài chính hết hiệu lực kể từ ngày 01/7/2015.'),
('68/2015/TT-BTC', '03/2005/QĐ-BTC', 'bai_bo', '2016-01-01', 'chac_chan', false, '15531', '3. Thông tư này có hiệu lực thi hành kể từ ngày 01/01/2016. Đối với các hợp đồng dịch vụ liên quan được thực hiện trước ngày 01/01/2016 mà đến ngày 01/01/2016 trở đi mới phát hành báo cáo dịch vụ tổng hợp hoặc báo cáo về các phát hiện thực tế thì phải áp dụng các chuẩn mực Việt Nam về dịch vụ liên quan ban hành theo Thông tư này. Chuẩn mực kiểm toán số 930 “Dịch vụ tổng hợp thông tin tài chính” ban hành theo Quyết định số 03/2005/QĐ-BTC ngày 18/01/2005 của Bộ trưởng Bộ Tài chính và Chuẩn mực kiểm toán số 920 “Kiểm tra thông tin tài chính trên cơ sở các thủ tục thỏa thuận trước” ban hành theo Quyết định số 195/2003/QĐ-BTC ngày 28/11/2003 của Bộ trưởng Bộ Tài chính hết hiệu lực kể từ ngày 01/01/2016.'),
('17/2015/TT-BLĐTBXH', '03/2005/TT-BLĐTBXH', 'bai_bo', '2015-06-10', 'chac_chan', false, '11847', '…2. Các Thông tư do Bộ Lao động - Thương binh và Xã hội ban hành sau đây hết hiệu lực thi hành kể từ ngày Thông tư này có hiệu lực thi hành, bao gồm: a) Thông tư số 01/2005/TT-BLĐTBXH ngày 05 tháng 01 năm 2005 hướng dẫn chuyển xếp lương cũ sang lương mới đối với Tổng giám đốc, Giám đốc, Phó tổng giám đốc, Phó giám đốc, Kế toán trưởng và công nhân, viên chức, nhân viên trong các công ty nhà nước theo Nghị định số 205/2004/NĐ-CP ngày 14 tháng 12 năm 2005 của Chính phủ; b) Thông tư số 04/1998/TT-BLĐTBXH ngày 04 tháng 4 năm 1998 hướng dẫn xây dựng tiêu chuẩn và thi nâng ngạch viên chức chuyên môn, nghiệp vụ trong doanh nghiệp nhà nước; c) Thông tư số 12/2003/TT-BLĐTBXH ngày 30 tháng 5 năm 2003 hướng dẫn thực hiện một số điều của Nghị định số 114/2002/NĐ-CP ngày 31 tháng 12 năm 2002 của Chính phủ về tiền lương đối với người lao động làm việc trong doanh nghiệp nhà nước; d) Thông tư số 18/2008/TT-BLĐTBXH ngày 16 tháng 9 năm 2008 sửa đổi, bổ sung Thông tư số 12/2003/TT-BLĐTBXH ngày 30 tháng 5 năm 2003 hướng dẫn thực hiện một số điều của Nghị định số 114/2002/NĐ-CP ngày 31 tháng 12 năm 2002 của Chính phủ về tiền lương; đ) Thông tư số 03/2005/TT-BLĐTBXH ngày 05 tháng 01 năm 2005 hướng dẫn th…'),
('67/2011/NĐ-CP', '03/2009/QĐ-TTg', 'bai_bo', '2012-01-01', 'can_xem_lai', false, '3965', '2. Quy định về thu phí xăng, dầu tại Nghị định số 78/2000/NĐ-CP ngày 26 tháng 12 năm 2000 của Chính phủ về phí xăng dầu và Quyết định số 03/2009/QĐ-TTg ngày 09 tháng 01 năm 2009 của Thủ tướng Chính phủ về điều chỉnh mức thu phí xăng, dầu hết hiệu lực thi hành kể từ ngày Nghị định này có hiệu lực thi hành.'),
('16/2016/TT-BXD', '03/2009/TT-BXD', 'bai_bo', '2016-08-15', 'chac_chan', false, '20436', '2. Quy định trước đây về Ban quản lý dự án đầu tư xây dựng được quy định tại Thông tư số 03/2009/TT-BXD ngày 26/3/2009 Quy định chi tiết một số nội dung của Nghị định số 12/2009/NĐ-CP ngày 12/02/2009 của Chính phủ về quản lý dự án đầu tư xây dựng công trình, Thông tư số 10/2013/TT-BXD ngày 25/7/2013 Quy định chi tiết một số nội dung về quản lý chất lượng công trình xây dựng và Thông tư số 09/2014/TT-BXD ngày 10/7/2014 Sửa đổi, bổ sung một số Điều tại các Thông tư hướng dẫn Nghị định số 15/2013/NĐ-CP ngày 06 tháng 02 năm 2013 của Chính phủ về quản lý chất lượng công trình xây dựng hết hiệu lực thi hành kể từ ngày Thông tư này có hiệu lực thi hành.'),
('01/2015/TTLT-TTCP-BNV', '03/2011/TTLT-BNV-TTCP', 'bai_bo', '2015-05-01', 'chac_chan', false, '9667', '1. Thông tư liên tịch này có hiệu lực kể từ ngày 01 tháng 5 năm 2015. Thông tư liên tịch số 03/2011/TTLT-BNV-TTCP ngày 06 tháng 5 năm 2011 của Bộ Nội vụ và Thanh tra Chính phủ hết hiệu lực kể từ ngày Thông tư liên tịch này có hiệu lực.'),
('49/2016/TTLT-BQP-BYT-BTC', '03/2012/TTLT-BQP-BYT-BTC', 'bai_bo', '2016-06-01', 'chac_chan', false, '19862', '2. Các văn bản sau đây hết hiệu lực thi hành kể từ ngày Thông tư này có hiệu lực thi hành: a) Thông tư liên tịch số 25/2010/TTLT-BQP-BYT-BTC ngày 05 tháng 3 năm 2010 của liên Bộ Quốc phòng, Bộ Y tế, Bộ Tài chính hướng dẫn quản lý, tổ chức thực hiện BHYT đối với người lao động trong quân đội và thân nhân quân nhân tại ngũ; b) Thông tư liên tịch số 03/2012/TTLT-BQP-BYT-BTC ngày 16 tháng 01 năm 2012 của liên Bộ Quốc phòng, Bộ Y tế, Bộ Tài chính hướng dẫn thực hiện BHYT đối với người làm công tác khác trong tổ chức cơ yếu và thân nhân người đang làm công tác cơ yếu. Trong quá trình tổ chức thực hiện nếu có vướng mắc, đề nghị phản ánh kịp thời về Bộ Quốc phòng, Bộ Y tế, Bộ Tài chính để xem xét, giải quyết./. KT. BỘ TRƯỞNG BỘ TÀI CHÍNH THỨ TRƯỞNG Đỗ Hoàng Anh Tuấn KT. BỘ TRƯỞNG BỘ Y TẾ THỨ TRƯỞNG Phạm Lê Tuấn KT. BỘ TRƯỞNG BỘ QUỐC PHÒNG THỨ TRƯỞNG Thượng tướng Nguyễn Thành Cung'),
('61/2015/NĐ-CP', '03/2014/NĐ-CP', 'bai_bo_mot_phan', '2015-09-01', 'chac_chan', false, '15220', '2. Quyết định số 71/2005/QĐ-TTg ngày 05 tháng 4 năm 2005 của Thủ tướng Chính phủ về cơ chế quản lý và điều hành Quỹ quốc gia về việc làm và Quyết định số 15/2008/QĐ-TTg ngày 23 tháng 01 năm 2008 của Thủ tướng Chính phủ về sửa đổi và bổ sung một số điều của Quyết định số 71/2005/QĐ-TTg; các quy định về chính sách hỗ trợ bộ đội xuất ngũ học nghề quy định tại Quyết định số 121/2009/QĐ-TTg ngày 09 tháng 10 năm 2009 của Thủ tướng Chính phủ về cơ chế hoạt động của các cơ sở dạy nghề thuộc Bộ Quốc phòng và chính sách hỗ trợ bộ đội xuất ngũ học nghề; Điều 4 Nghị định số 03/2014/NĐ-CP ngày 16 tháng 01 năm 2014 của Chính phủ quy định chi tiết thi hành một số điều của Bộ luật Lao động về việc làm hết hiệu lực thi hành kể từ ngày Nghị định này có hiệu lực thi hành.'),
